from solution import get_closest_vowel
import pytest
from hypothesis import given
import hypothesis.strategies as st

VOWELS = set("aeiouAEIOU")

def reference(word):
    for i in range(len(word) - 2, 0, -1):
        if word[i] in VOWELS and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS:
            return word[i]
    return ""

letters = st.text(alphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", min_size=0, max_size=12)

def test_examples_yogurt():
    assert get_closest_vowel("yogurt") == "u"

def test_examples_FULL():
    assert get_closest_vowel("FULL") == "U"

def test_examples_quick():
    assert get_closest_vowel("quick") == ""

def test_examples_ab():
    assert get_closest_vowel("ab") == ""

@given(letters)
def test_property_matches_reference_model(word):
    assert get_closest_vowel(word) == reference(word)

@given(letters)
def test_property_result_is_vowel_or_empty(word):
    r = get_closest_vowel(word)
    assert r == "" or (len(r) == 1 and r in VOWELS)

@given(letters)
def test_property_result_between_two_consonants(word):
    r = get_closest_vowel(word)
    if r != "":
        # find rightmost occurrence equal to r that satisfies condition in reference sense
        # at minimum: there exists a qualifying position holding exactly r
        found = False
        for i in range(1, len(word) - 1):
            if word[i] == r and word[i] in VOWELS and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS:
                found = True
                break
        assert found, f"result {r!r} not between consonants in {word!r}"

@given(letters)
def test_property_result_is_rightmost_qualifier(word):
    r = get_closest_vowel(word)
    if r == "":
        # no position qualifies
        for i in range(1, len(word) - 1):
            assert not (word[i] in VOWELS and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS)
    else:
        # locate returned position as rightmost qualifier
        rightmost = -1
        for i in range(1, len(word) - 1):
            if word[i] in VOWELS and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS:
                rightmost = i
        assert rightmost != -1
        assert word[rightmost] == r

@given(letters)
def test_property_case_exactly_preserved(word):
    r = get_closest_vowel(word)
    if r != "":
        # result must appear verbatim in word, case-sensitive
        assert r in word
        # opposite case must not be confused: reference equality already checks this
        assert r == reference(word)

def test_property_uppercase_preserved_FULL():
    assert get_closest_vowel("FULL") == "U"
    assert get_closest_vowel("AbCDEfG") != "" or True  # smoke
    # uppercase vowel between consonants must stay uppercase
    assert get_closest_vowel("BAC") == "A"
    assert get_closest_vowel("bAc") == "A"
    assert get_closest_vowel("BaC") == "a"
    assert get_closest_vowel("MOM") == "O"
    assert get_closest_vowel("mom") == "o"

def test_property_beginning_ending_vowels_do_not_count():
    assert get_closest_vowel("ab") == ""
    assert get_closest_vowel("a") == ""
    assert get_closest_vowel("b") == ""
    assert get_closest_vowel("") == ""
    assert get_closest_vowel("abA") == ""
    assert get_closest_vowel("AbA") == ""
    # vowel at index 0 or last index alone must not be returned
    assert get_closest_vowel("aBC") == ""
    assert get_closest_vowel("BCa") == ""
    assert get_closest_vowel("EBC") == ""
    assert get_closest_vowel("BCe") == ""

def test_property_short_words_empty():
    assert get_closest_vowel("") == ""
    assert get_closest_vowel("a") == ""
    assert get_closest_vowel("Z") == ""
    assert get_closest_vowel("ab") == ""
    assert get_closest_vowel("ae") == ""
    assert get_closest_vowel("ba") == ""

def test_property_all_consonants_empty():
    assert get_closest_vowel("bcdfg") == ""
    assert get_closest_vowel("BCDFG") == ""
    assert get_closest_vowel("yYy") == ""
    assert get_closest_vowel("quick") == ""

def test_property_all_vowels_empty():
    assert get_closest_vowel("aei") == ""
    assert get_closest_vowel("AEI") == ""
    assert get_closest_vowel("aeiou") == ""
    assert get_closest_vowel("AEIOUaeiou") == ""

@given(st.text(alphabet="BCDFGHJKLMNPQRSTVWXYZbcdfghjklmnpqrstvwxyz", min_size=1, max_size=5),
       st.sampled_from(sorted(VOWELS)),
       st.text(alphabet="BCDFGHJKLMNPQRSTVWXYZbcdfghjklmnpqrstvwxyz", min_size=1, max_size=5))
def test_property_constructed_qualifier_from_right(left, vowel, right):
    word = left + vowel + right
    # ensure the constructed middle is the rightmost qualifier by making suffix vowel-free
    # right is all consonants, left is all consonants, so middle qualifies unless at edge
    if len(word) >= 3 and 1 <= len(left) <= len(word) - 2:
        # middle index = len(left); neighbors are consonants by construction
        assert get_closest_vowel(word) == vowel
